SELECT FROM public.build_systems WHERE game_id = #{gameId}
AND (strpos(lower(system_key), lower(#{keyword})) > 0 OR strpos(lower(name), lower(#{keyword})) > 0)
ORDER BY sort_order ASC, system_key ASC

SELECT COUNT(*) FROM public.build_systems
WHERE game_id = #{gameId} AND lower(btrim(name)) = lower(btrim(#{name}))
AND system_key <> #{excludeKey}

SELECT FROM public.build_groups WHERE game_id = #{gameId} AND system_key = #{systemKey}
AND (strpos(lower(group_key), lower(#{keyword})) > 0 OR strpos(lower(name), lower(#{keyword})) > 0)
ORDER BY sort_order ASC, group_key ASC

SELECT COUNT(*) FROM public.build_groups
WHERE game_id = #{gameId} AND system_key = #{systemKey} AND lower(btrim(name)) = lower(btrim(#{name}))
AND group_key <> #{excludeKey}

SELECT FROM public.build_options WHERE game_id = #{gameId} AND system_key = #{systemKey}
AND (strpos(lower(option_key), lower(#{keyword})) > 0 OR strpos(lower(name), lower(#{keyword})) > 0)
ORDER BY name ASC, option_key ASC

SELECT COUNT(*) FROM public.build_options
WHERE game_id = #{gameId} AND system_key = #{systemKey} AND lower(btrim(name)) = lower(btrim(#{name}))
AND option_key <> #{excludeKey}
